DROP TABLE IF EXISTS `yard_placement_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `yard_placement_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `terminal_recommendation_id` bigint unsigned NOT NULL,
  `rec_type` enum('TIMING','YARD_PLACEMENT','STORAGE_ALLOCATION') NOT NULL DEFAULT 'YARD_PLACEMENT',
  `manifest_entry_id` bigint unsigned NOT NULL,
  `yard_block_id` bigint unsigned NOT NULL,
  `yard_slot_id` bigint unsigned DEFAULT NULL COMMENT 'Optional; coordination level is block (FR-2.2.3)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ypi_rec_container` (`terminal_recommendation_id`,`manifest_entry_id`),
  KEY `fk_ypi_block` (`yard_block_id`),
  KEY `fk_ypi_manifest` (`manifest_entry_id`),
  KEY `fk_ypi_slot` (`yard_slot_id`,`yard_block_id`),
  KEY `fk_ypi_tr` (`terminal_recommendation_id`,`rec_type`),
  CONSTRAINT `fk_ypi_block` FOREIGN KEY (`yard_block_id`) REFERENCES `yard_blocks` (`id`),
  CONSTRAINT `fk_ypi_manifest` FOREIGN KEY (`manifest_entry_id`) REFERENCES `container_manifest_entries` (`id`),
  CONSTRAINT `fk_ypi_slot` FOREIGN KEY (`yard_slot_id`, `yard_block_id`) REFERENCES `yard_slots` (`id`, `yard_block_id`),
  CONSTRAINT `fk_ypi_tr` FOREIGN KEY (`terminal_recommendation_id`, `rec_type`) REFERENCES `terminal_recommendations` (`id`, `rec_type`),
  CONSTRAINT `chk_ypi_type` CHECK ((`rec_type` = _utf8mb4'YARD_PLACEMENT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
DROP TABLE IF EXISTS `yard_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `yard_runs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `terminal_recommendation_id` bigint unsigned NOT NULL,
  `triggered_by` bigint unsigned DEFAULT NULL,
  `status` enum('QUEUED','RUNNING','DONE','FAILED','REPLACED') NOT NULL DEFAULT 'QUEUED',
  `outcome` enum('YARD_REC_GENERATED','GENERATION_FAILED') DEFAULT NULL,
  `error_category` enum('INVALID_ENVELOPE','PRECONDITION_FAILED','DATA_UNAVAILABLE','CONFIGURATION_ERROR','INFEASIBLE','TIMEOUT','INTERNAL_ERROR') DEFAULT NULL,
  `retry_count` tinyint NOT NULL DEFAULT '0',
  `result_detail` json DEFAULT NULL,
  `worker_version` varchar(40) DEFAULT NULL,
  `queued_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `active_key` bigint unsigned GENERATED ALWAYS AS (if((`status` in (_utf8mb4'QUEUED',_utf8mb4'RUNNING')),`terminal_recommendation_id`,NULL)) STORED,
  `result_handled_at` datetime DEFAULT NULL COMMENT 'Set by the Backend when it has handled the C-06 result (Backend only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_yr_active` (`active_key`),
  KEY `idx_yr_tr` (`terminal_recommendation_id`),
  KEY `fk_yr_user` (`triggered_by`),
  CONSTRAINT `fk_yr_tr` FOREIGN KEY (`terminal_recommendation_id`) REFERENCES `terminal_recommendations` (`id`),
  CONSTRAINT `fk_yr_user` FOREIGN KEY (`triggered_by`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_yr_error` CHECK (((`status` = _utf8mb4'FAILED') = (`error_category` is not null))),
  CONSTRAINT `chk_yr_finished` CHECK (((`status` in (_utf8mb4'QUEUED',_utf8mb4'RUNNING',_utf8mb4'REPLACED')) or (`finished_at` is not null))),
  CONSTRAINT `chk_yr_outcome` CHECK ((((`status` = _utf8mb4'DONE') and (`outcome` = _utf8mb4'YARD_REC_GENERATED')) or ((`status` = _utf8mb4'FAILED') and (`outcome` = _utf8mb4'GENERATION_FAILED')) or ((`status` in (_utf8mb4'QUEUED',_utf8mb4'RUNNING',_utf8mb4'REPLACED')) and (`outcome` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
DROP TABLE IF EXISTS `yard_slots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `yard_slots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `yard_block_id` bigint unsigned NOT NULL,
  `bay` int NOT NULL,
  `row_no` int NOT NULL,
  `tier` int NOT NULL,
  `status` enum('ACTIVE','BLOCKED') NOT NULL DEFAULT 'ACTIVE' COMMENT 'Administrative only; occupied = container_id IS NOT NULL',
  `container_id` bigint unsigned DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'Version token for the 409 check (microseconds)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ys_id_block` (`id`,`yard_block_id`),
  UNIQUE KEY `uq_ys_position` (`yard_block_id`,`bay`,`row_no`,`tier`),
  UNIQUE KEY `container_id` (`container_id`),
  CONSTRAINT `fk_ys_block` FOREIGN KEY (`yard_block_id`) REFERENCES `yard_blocks` (`id`),
  CONSTRAINT `fk_ys_container` FOREIGN KEY (`container_id`) REFERENCES `containers` (`id`),
  CONSTRAINT `chk_ys_blocked_empty` CHECK (((`status` = _utf8mb4'ACTIVE') or (`container_id` is null))),
  CONSTRAINT `chk_ys_position` CHECK (((`bay` > 0) and (`row_no` > 0) and (`tier` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
DROP TABLE IF EXISTS `yard_zone_types`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `yard_zone_types` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
