  `name` varchar(80) NOT NULL,
  `zone_detail` enum('NONE','REEFER','DANGEROUS_GOODS','OOG') NOT NULL DEFAULT 'NONE' COMMENT 'Which detail table zones of this type use; chosen by the admin when adding a type',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_yzt_id_detail` (`id`,`zone_detail`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
DROP TABLE IF EXISTS `yard_zones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `yard_zones` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `container_yard_id` bigint unsigned NOT NULL COMMENT 'storage_facility.id of a CONTAINER_YARD',
  `detail_kind` enum('NONE','WAREHOUSE','CONTAINER_YARD','TANK') NOT NULL DEFAULT 'CONTAINER_YARD' COMMENT 'Same ENUM as storage_facility (FK compares ENUM index)',
  `yard_zone_type_id` bigint unsigned NOT NULL,
  `zone_detail` enum('NONE','REEFER','DANGEROUS_GOODS','OOG') NOT NULL COMMENT 'Copy of yard_zone_type.zone_detail, enforced by composite FK',
  `code` varchar(30) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_yz_id_detail` (`id`,`zone_detail`),
  UNIQUE KEY `uq_yz_yard_code` (`container_yard_id`,`code`),
  KEY `fk_yz_type` (`yard_zone_type_id`,`zone_detail`),
  KEY `fk_yz_yard` (`container_yard_id`,`detail_kind`),
  CONSTRAINT `fk_yz_type` FOREIGN KEY (`yard_zone_type_id`, `zone_detail`) REFERENCES `yard_zone_types` (`id`, `zone_detail`),
  CONSTRAINT `fk_yz_yard` FOREIGN KEY (`container_yard_id`, `detail_kind`) REFERENCES `storage_facilities` (`id`, `detail_kind`),
  CONSTRAINT `chk_yz_kind` CHECK ((`detail_kind` = _utf8mb4'CONTAINER_YARD'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Capacity/occupancy are derived from yard_slot.';
